        // ---- THE FIXED FORM, form byte 3 (docs/SPEC-TABLES.md §3.4) ----
        //
        // A record is an eight-byte hash of the writer's vocabulary block and then
        // the values in declared order, every field at its declared storage width.
        // The writer is the constant bytes memcpy'd and then stores; the reader is
        // ONE loop over ONE plan, the identity plan here and a plan compiled from
        // the writer's own block for anybody else.

        // PaddedRow's stores. The template — the hash, then zeros — is memcpy'd first,
        // which is also what zero-fills every byte of declared slack.
        public static void PaddedRowFixedWriteBody(Span<byte> b, PaddedRow value)
        {
            if (value == null) return;
            b[0] = unchecked((byte)value.Tag);
            BinaryPrimitives.WriteDoubleLittleEndian(b.Slice(1), value.Value);
            b.Slice(9)[0] = (byte)(value.Flag ? 1 : 0);
            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(10), (int)value.Id);
            int len_label = value.Label != null ? value.LabelLength : 0;
            System.Diagnostics.Debug.Assert(len_label <= 15);
            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(14), len_label);
            if (len_label > 0) { value.Label.AsSpan(0, len_label).CopyTo(b.Slice(18)); }
            if (value.Slots != null) { MemoryMarshal.AsBytes(value.Slots.AsSpan(0, Math.Min(value.Slots.Length, 4))).CopyTo(b.Slice(33)); }
            if (value.Teams.Slots != null) { value.Teams.Slots.AsSpan(0, Math.Min(value.Teams.Slots.Length, 4)).CopyTo(b.Slice(41)); }
            b[45] = (byte)(value.CounterPresent ? 1 : 0);
            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(46), (int)value.Counter);
        }

        // PaddedFrame's stores. The template — the hash, then zeros — is memcpy'd first,
        // which is also what zero-fills every byte of declared slack.
        public static void PaddedFrameFixedWriteBody(Span<byte> b, PaddedFrame value)
        {
            if (value == null) return;
            b[0] = unchecked((byte)value.Marker);
            BinaryPrimitives.WriteInt64LittleEndian(b.Slice(1), (long)value.Stamp);
            int count_rows = value.RowsCount;
            System.Diagnostics.Debug.Assert(count_rows >= 0 && count_rows <= 64); // the declared count is the bound (§3.4)
            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(9), count_rows);
            if (value.Rows != null)
            {
                for (int i = 0; i < count_rows && i < value.Rows.Length; ++i)
                {
                    PaddedRowFixedWriteBody(b.Slice(13 + i * 50), value.Rows[i]);
                }
            }
            int len_blob = value.Blob != null ? value.BlobLength : 0;
            System.Diagnostics.Debug.Assert(len_blob <= 12);
            BinaryPrimitives.WriteInt32LittleEndian(b.Slice(3213), len_blob);
            if (len_blob > 0) { value.Blob.AsSpan(0, len_blob).CopyTo(b.Slice(3217)); }
        }

