        public static long PaddedRowFixedMeasure(long count)
        {
            return TableFixedWire.HeaderBytes + 4 + PaddedRowFixedLayoutBytes + count * PaddedRowFixedRecordBytes;
        }

        public static long PaddedRowFixedSave(ReadOnlySpan<PaddedRow> values, Span<byte> buffer)
        {
            long need = PaddedRowFixedMeasure(values.Length);
            if (values.Length < 0 || buffer.Length < need) { return -1; }
            buffer.Slice(0, TableFixedWire.HeaderBytes).Clear();
            buffer[0] = TableFixedWire.Form;
            BinaryPrimitives.WriteUInt64LittleEndian(buffer.Slice(TableFixedWire.HashAt), PaddedRowFixedHash);
            BinaryPrimitives.WriteUInt32LittleEndian(buffer.Slice(TableFixedWire.HeaderBytes), (uint)PaddedRowFixedLayoutBytes);
            PaddedRowFixedLayout.CopyTo(buffer.Slice(TableFixedWire.HeaderBytes + 4));
            Span<byte> at = buffer.Slice(TableFixedWire.HeaderBytes + 4 + (int)PaddedRowFixedLayoutBytes);
            for (int k = 0; k < values.Length; ++k)
            {
                BinaryPrimitives.WriteUInt64LittleEndian(at, PaddedRowFixedHash);
                at.Slice(8, (int)PaddedRowFixedBodyBytes).Clear();
                PaddedRowFixedWriteBody(at.Slice(8), values[k]);
                at = at.Slice((int)PaddedRowFixedRecordBytes);
            }
            return need;
        }

        public static long PaddedRowFixedSave(PaddedRow[] values, Span<byte> buffer)
        {
            return PaddedRowFixedSave((ReadOnlySpan<PaddedRow>)values, buffer);
        }

        public static long PaddedRowFixedSave(PaddedRow value, Span<byte> buffer)
        {
            ReadOnlySpan<PaddedRow> span = MemoryMarshal.CreateReadOnlySpan(ref value, 1);
            return PaddedRowFixedSave(span, buffer);
        }

        public static long PaddedRowFixedLoad(
            Span<PaddedRow> values,
            ReadOnlySpan<byte> data,
            Span<TableFixedEntry> plan,
            TableReport report = null)
        {
            if (data.Length < TableFixedWire.HeaderBytes + 4)
            {
                if (report != null) { report.Malformed = true; report.Verdict = TableWire.Verdict.Damaged; }
                return -1;
            }
            if (data[0] != TableFixedWire.Form)
            {
                if (report != null)
                {
                    report.Refused = true;
                    report.Reason = data[0] == 2 ? "message_form_as_file"
                                  : data[0] < TableFixedWire.Form ? "previous_form"
                                  : "newer_form";
                    report.Verdict = TableWire.Verdict.Refused;
                }
                return -1;
            }
            uint layout_bytes = BinaryPrimitives.ReadUInt32LittleEndian(data.Slice(TableFixedWire.HeaderBytes));
            if ((long)layout_bytes + TableFixedWire.HeaderBytes + 4 > data.Length)
            {
                if (report != null) { report.Refused = true; report.Reason = "layout_malformed"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            ReadOnlySpan<byte> layout = data.Slice(TableFixedWire.HeaderBytes + 4, (int)layout_bytes);
            ulong hash = TableFixedWire.HashOf(layout);
            ReadOnlySpan<byte> at = data.Slice(TableFixedWire.HeaderBytes + 4 + (int)layout_bytes);
            int rest = data.Length - TableFixedWire.HeaderBytes - 4 - (int)layout_bytes;
            ReadOnlySpan<TableFixedEntry> entries = PaddedRowFixedPlan;
            long record_bytes = PaddedRowFixedRecordBytes;
            ReadOnlySpan<byte> planBytes = ReadOnlySpan<byte>.Empty;
            if (hash != PaddedRowFixedHash)
            {
                if (!TableFixedWire.ParseLayout(layout, out TableFixedLayoutView parsed, out string why))
                {
                    if (report != null) { report.Refused = true; report.Reason = why; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                int made = TableFixedWire.Compile(parsed, PaddedRowFixedLayout, PaddedRowFixedDst, plan, report);
                if (made < 0)
                {
                    if (report != null) { report.Refused = true; report.Reason = "plan_too_large"; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                entries = plan.Slice(0, made);
                record_bytes = 8 + (long)TableFixedWire.EntryAt(parsed, 0).Size;
                planBytes = MemoryMarshal.AsBytes(plan);
            }
            if (BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(TableFixedWire.HashAt)) != hash)
            {
                if (report != null) { report.Refused = true; report.Reason = "layout_malformed"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            if (record_bytes <= 8 || rest % record_bytes != 0)
            {
                if (report != null) { report.Malformed = true; report.Verdict = TableWire.Verdict.Damaged; }
                return -1;
            }
            long n = rest / record_bytes;
            if (n > values.Length)
            {
                if (report != null) { report.Refused = true; report.Reason = "batch_too_large"; report.Verdict = TableWire.Verdict.Refused; }
                return -1;
            }
            for (int k = 0; k < n; ++k)
            {
                if (values[k] == null) { values[k] = new PaddedRow(); }
                TableReset(values[k]);
                if (BinaryPrimitives.ReadUInt64LittleEndian(at) != hash)
                {
                    if (report != null) { report.Refused = true; report.Reason = "no_layout"; report.Verdict = TableWire.Verdict.Refused; }
                    return -1;
                }
                TableFixedWire.Run(entries, PaddedRowFixedSlots, at.Slice(8), values[k], report, planBytes);
                at = at.Slice((int)record_bytes);
            }
            if (report != null) { report.Verdict = TableWire.Verdict.Ok; }
            return n;
        }

        public static long PaddedRowFixedLoad(PaddedRow[] values, ReadOnlySpan<byte> data, Span<TableFixedEntry> plan, TableReport report = null)
        {
            return PaddedRowFixedLoad((Span<PaddedRow>)values, data, plan, report);
        }

        public static long PaddedRowFixedLoad(PaddedRow value, ReadOnlySpan<byte> data, Span<TableFixedEntry> plan, TableReport report = null)
        {
            Span<PaddedRow> span = MemoryMarshal.CreateSpan(ref value, 1);
            return PaddedRowFixedLoad(span, data, plan, report);
        }

        public static void TableFixedRun(
            ReadOnlySpan<TableFixedEntry> plan,
            ReadOnlySpan<byte> src,
            PaddedRow dst,
            TableReport report = null,
            ReadOnlySpan<byte> planBytes = default)
        {
            TableFixedWire.Run(plan, PaddedRowFixedSlots, src, dst, report, planBytes);
        }

